const RATE = {{rate}}, BURST = {{burst}};
let tokens = BURST, last = performance.now(), ok = 0, no = 0, flash = 0, flashOk = true;
addEventListener('click', () => {
  if (tokens >= 1) { tokens -= 1; ok++; flashOk = true; } else { no++; flashOk = false; }
  flash = 1;
});
function frame(now) {
  tokens = Math.min(BURST, tokens + ((now - last) / 1000) * RATE); last = now;
  flash *= 0.92;
  ctx.clearRect(0, 0, W(), H());
  for (let i = 0; i < BURST; i++) {
    ctx.fillStyle = i < Math.floor(tokens) ? '#4ade80' : '#374151';
    ctx.fillRect(16 + i * 26, 60, 20, 34);
  }
  ctx.fillStyle = '#eee'; ctx.font = '14px system-ui';
  ctx.fillText('화면을 눌러 요청 — 통과 ' + ok + ' · 429 ' + no, 16, 30);
  ctx.globalAlpha = flash;
  ctx.fillStyle = flashOk ? '#4ade80' : '#f87171';
  ctx.fillRect(0, H() - 8, W(), 8);
  ctx.globalAlpha = 1;
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

// 초당 채워지는 양(rate)과 최대 저장량(burst)
function 허용(state, now, rate = 5, burst = 20) {
  const 채움 = (now - state.at) / 1000 * rate;
  state.tokens = Math.min(burst, state.tokens + 채움);
  state.at = now;
  if (state.tokens < 1) return false;
  state.tokens -= 1;
  return true;
}
// 평소 여유분을 모아 뒀다가 순간 몰림을 흡수한다
// 고정 창 방식은 창 경계에서 두 배가 통과한다 (59초·61초)
